const raw = $json.html;
if (typeof raw !== 'string' || !raw.includes('Fund Top Holdings')) throw new Error('Official XLP page did not contain the holdings section');
const html = raw.replace(/&#34;/g, '"').replace(/&#43;/g, '+').replace(/&amp;/g, '&').replace(/&reg;/g, '');
const section = html.match(/<h3>Fund Top Holdings[\s\S]*?<\/table>/i)?.[0];
if (!section) throw new Error('Could not isolate official XLP top holdings table');
const dateText = section.match(/as of\s+([A-Z][a-z]{2}\s+\d{1,2}\s+\d{4})/i)?.[1];
if (!dateText) throw new Error('Official XLP holdings date is missing');
const publishedDate = new Date(dateText + ' 00:00:00 UTC').toISOString().slice(0, 10);
const baselineDate = '2026-09-14';
if (publishedDate <= baselineDate) return [];
const holdings = [];
const rowPattern = /<tr>[\s\S]*?<td[^>]*data-label="Name:"[^>]*>([\s\S]*?)<\/td>[\s\S]*?<td[^>]*data-label="Shares Held:"[^>]*>([\s\S]*?)<\/td>[\s\S]*?<td[^>]*data-label="Weight:"[^>]*>([\s\S]*?)<\/td>[\s\S]*?<\/tr>/gi;
const clean = (value) => value.replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
for (const match of section.matchAll(rowPattern)) holdings.push({name:clean(match[1]),shares_held:clean(match[2]),weight:clean(match[3])});
if (holdings.length !== 10) throw new Error('Expected 10 official XLP top holdings, found ' + holdings.length);
const expenseRatio = html.match(/"gross-expense-ratio":\{[\s\S]*?"value":"([^"]+)"/)?.[1] ?? null;
const packet = {ticker:'XLP',fund:'State Street Consumer Staples Select Sector SPDR ETF',holdings_as_of:publishedDate,gross_expense_ratio:expenseRatio,top_holdings:holdings,source_uri:'https://www.ssga.com/us/en/individual/etfs/state-street-consumer-staples-select-sector-spdr-etf-xlp'};
return [{json:{
  source_uri:packet.source_uri,
  source_title:'State Street XLP fund top holdings as of ' + publishedDate,
  source_published_at:publishedDate,
  retrieved_at:new Date().toISOString(),
  packet_material:JSON.stringify(packet),
  factual_summary:"State Street's official XLP page reports top holdings as of " + publishedDate + '. The largest displayed holding is ' + holdings[0].name + ' at ' + holdings[0].weight + '; the page lists a gross expense ratio of ' + (expenseRatio ?? 'not parsed') + '.',
  interpretation_note:'A new official fund-page observation was detected. Consumer-staples exposure, overlap, portfolio role, valuation and risks require human review.',
  limitations:'Top-ten fund-page holdings only, not a complete look-through or broker position record. Data may be delayed or revised. No lane approval, position size, recommendation or trade is implied.',
  dedupe_key:'state-street:xlp:top-holdings:' + publishedDate
}}];
